#include <string>
#include <utility>
#include <vector>

// Floods the '.' region containing (x, y) with '~' and returns how many cells changed.
int floodFill(std::vector<std::string>& map, int x, int y)
{
    std::vector<std::pair<int, int>> toVisit;   // cells still to look at
    int changed{ 0 };
    toVisit.push_back({ x, y });
    while (!toVisit.empty())
    {
        const auto [cx, cy] = toVisit.back();
        toVisit.pop_back();
        if (cy < 0 || cy >= static_cast<int>(map.size())) continue;
        if (cx < 0 || cx >= static_cast<int>(map[cy].size())) continue;
        if (map[cy][cx] != '.') continue;
        map[cy][cx] = '~';
        ++changed;
        toVisit.push_back({ cx + 1, cy });
        toVisit.push_back({ cx - 1, cy });
        toVisit.push_back({ cx, cy + 1 });
        toVisit.push_back({ cx, cy - 1 });
    }
    return changed;
}

unitTests:
TEST("the example")
{
    std::vector<std::string> map{ "#######", "#..#..#", "#..#..#", "####..#", "#######" };
    CHECK_EQ(floodFill(map, 1, 1), 4);
    CHECK_EQ(map[1], std::string("#~~#..#"));
    CHECK_EQ(map[3], std::string("####..#"));
}
TEST("the other room")
{
    std::vector<std::string> map{ "#######", "#..#..#", "#..#..#", "####..#", "#######" };
    CHECK_EQ(floodFill(map, 4, 3), 6);
    CHECK_EQ(map[1], std::string("#..#~~#"));
}
TEST("starting on a wall changes nothing")
{
    std::vector<std::string> map{ "###", "#.#", "###" };
    CHECK_EQ(floodFill(map, 0, 0), 0);
    CHECK_EQ(map[1], std::string("#.#"));
}
TEST("starting outside the map changes nothing")
{
    std::vector<std::string> map{ "..", ".." };
    CHECK_EQ(floodFill(map, 5, 0), 0);
    CHECK_EQ(floodFill(map, 0, -1), 0);
}
TEST("diagonals do not connect")
{
    std::vector<std::string> map{ ".#", "#." };
    CHECK_EQ(floodFill(map, 0, 0), 1);
    CHECK_EQ(map[1], std::string("#."));
}
TEST("a big open map does not overflow the stack")
{
    std::vector<std::string> map(1500, std::string(1500, '.'));
    CHECK_EQ(floodFill(map, 0, 0), 1500 * 1500);
    CHECK_EQ(map[1499][1499], '~');
}

